def badge(estimate):
    return {
      'validated':   estimate.model.vv_passed,
      'calibrated':  estimate.calibration_ok,
      'inputs_ok':   not estimate.any_input_imputed_critical,
      'in_dist':     estimate.ood_score < OOD_THRESHOLD,
    }  # 4 booleans -> green/amber/red glyphs, detail one click away

def present(active_alarms, plant_mode, causal_graph):
    active = drop_shelved(active_alarms, plant_mode)      # audited shelving
    if rate(active) > FLOOD_THRESHOLD:
        roots = causal_graph.root_causes(active)          # collapse cascade
        return grouped_view(roots, expandable=True, flood_mode=True)
    return ranked_view(active)                            # normal triage

def draw_shadow(live, shadow):
    plot(live.t, live.y, style='measured')          # solid, current
    plot(shadow.t, shadow.mu, style='forecast')      # distinct, leading
    fan(shadow.t, shadow.mu, shadow.sigma_of_h)      # widening band vs horizon
    for c in shadow.envelope_limits:
        mark_crossing(shadow, c)                      # highlight projected breaches
